console.log("GO360 script cargado");document.addEventListener("DOMContentLoaded",()=>{const e=document.querySelector(".top-bar__hamburger"),o=document.querySelector(".mobile-menu");if(e&&o){const t=()=>o.classList.remove("open");e.addEventListener("click",e=>{e.stopPropagation(),o.classList.toggle("open")}),document.addEventListener("click",t),document.addEventListener("keyup",e=>{"Escape"===e.key&&t()}),o.addEventListener("click",e=>e.stopPropagation())}const c=document.querySelector(".top-bar__profile-link"),n=document.querySelector(".top-bar__profile-menu");if(c&&n){const e=()=>n.classList.remove("visible");c.addEventListener("click",o=>{o.stopPropagation(),n.classList.toggle("visible")}),document.addEventListener("click",e),document.addEventListener("keyup",o=>{"Escape"===o.key&&e()}),n.addEventListener("click",e=>e.stopPropagation())}});
